-- Questões originais: Fernandes e Abreu, Implantando a Governança de TI, 4ª edição, Brasport, 2014.
-- Contexto histórico da edição: COBIT 5, ITIL 2011 e versões de normas nela apresentadas.
-- Não são questões oficiais nem exercícios transcritos do livro.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens entram como rascunhos. Revise antes de publicar.
-- Páginas referem-se ao arquivo PDF fornecido, não à paginação impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve registros existentes.
-- Capítulo 6: Modelos Abrangentes de Governança de TI — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('0052f4db-1785-5bd2-8e27-ba58b9740a88', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Governança de TI', 'Fácil', 'Quais tarefas compõem o modelo da ISO/IEC 38500 apresentado?', '["Comprar, depreciar e descartar.","Codificar, testar e instalar.","Projetar, vender e faturar.","Recrutar, contratar e demitir.","Avaliar, dirigir e monitorar."]'::jsonb, 4, 'As tarefas orientam a atuação dos dirigentes sobre o uso da TI.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.1.3, páginas 219–223 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('17cd7f78-9c84-552c-97fe-02ac783b33e1', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Governança de TI', 'Fácil', 'A aplicabilidade da ISO/IEC 38500, conforme o livro, abrange:', '["Somente multinacionais.","Somente órgãos federais.","Apenas bancos.","Organizações públicas e privadas de diferentes portes.","Exclusivamente empresas de software."]'::jsonb, 3, 'A norma é apresentada como aplicável a organizações de vários tipos e tamanhos.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.1.1, páginas 218–219 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5a8236df-257c-58bc-80b8-376935c5e0cb', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Governança de TI', 'Médio', 'Associar responsabilidade a autoridade adequada atende a qual princípio da ISO/IEC 38500?', '["Comportamento humano.","Conformidade.","Responsabilidade.","Aquisição.","Desempenho."]'::jsonb, 2, 'Quem responde por uma ação precisa ter autoridade para desempenhá-la.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.1.3, páginas 219–223 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('77f4c140-55e0-5a2d-8fa1-b41814b81656', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Governança de TI', 'Médio', 'Equilibrar benefícios, custos, oportunidades e riscos ao comprar TI atende a qual princípio?', '["Conformidade exclusivamente.","Comportamento humano.","Responsabilidade exclusivamente.","Desempenho exclusivamente.","Aquisição."]'::jsonb, 4, 'A aquisição deve ter justificativa e decisão transparente.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.1.3, páginas 219–223 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bf1819ba-aed8-5d0f-a021-e2bd2e802ce4', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Governança de TI', 'Médio', 'Considerar capacidades atuais e futuras da TI na estratégia de negócio corresponde a:', '["Estratégia.","Responsabilidade apenas.","Desempenho apenas.","Aquisição apenas.","Conformidade apenas."]'::jsonb, 0, 'O princípio articula planejamento do negócio e possibilidades de TI.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.1.3, páginas 219–223 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9fa7d725-fba4-5a62-a7f6-6a9023302be5', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Governança de TI', 'Médio', 'Respeitar necessidades das pessoas afetadas pelas decisões de TI corresponde a:', '["Responsabilidade exclusivamente.","Aquisição.","Estratégia exclusivamente.","Conformidade exclusivamente.","Comportamento humano."]'::jsonb, 4, 'O princípio considera as pessoas nos processos e decisões.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.1.3, páginas 219–223 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ba3c29bb-518a-5697-9b5c-5f576d36b38a', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Governança de TI', 'Fácil', 'No COBIT 5, a criação de valor procura equilibrar principalmente:', '["Apenas custos de licenças.","Exclusivamente rapidez e volume.","Somente número de fornecedores.","Somente quantidade de projetos.","Benefícios, riscos e recursos."]'::jsonb, 4, 'A satisfação das partes interessadas exige o equilíbrio dessas dimensões.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.2.3, páginas 227–233 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2d72c0cd-9cd2-56eb-baec-cdf9ee7cd0a2', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Governança de TI', 'Médio', 'Cobrir a organização de ponta a ponta significa que o COBIT 5:', '["Substitui toda gestão empresarial.","Integra governança de TI e governança corporativa.","Abrange apenas sistemas financeiros.","Exclui atividades terceirizadas.","Se limita ao departamento de infraestrutura."]'::jsonb, 1, 'O escopo considera o uso corporativo da informação e da tecnologia.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.2.3, páginas 227–233 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('73e30eca-27e8-58c3-9990-c972cd86ca14', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Governança de TI', 'Médio', 'Qual princípio permite ao COBIT 5 articular ITIL, TOGAF e normas ISO?', '["Aplicar um framework integrado único.","Eliminar processos especializados.","Usar apenas habilitadores técnicos.","Restringir a governança à infraestrutura.","Exigir um único fornecedor."]'::jsonb, 0, 'O framework funciona como integrador de orientações compatíveis.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.2.3, páginas 227–233 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6610444c-d0f8-5696-935d-79cbb3aa8844', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Governança de TI', 'Fácil', 'Quantas categorias de habilitadores são descritas no COBIT 5?', '["Cinco.","Dez.","Quatro.","Sete.","Três."]'::jsonb, 3, 'Os habilitadores permitem uma visão além dos processos.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.2.3, páginas 227–233 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('714c257e-8dc2-5c12-8e0c-d4b8b4b5f79e', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Governança de TI', 'Médio', 'Qual alternativa é uma categoria de habilitador do COBIT 5?', '["Apenas custo por chamado.","Exclusivamente prazo de projeto.","Somente retorno contábil.","Cultura, ética e comportamento.","Somente participação de mercado."]'::jsonb, 3, 'Fatores humanos também influenciam governança e gerenciamento.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.2.3, páginas 227–233 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3aae0667-2614-5dca-9020-1f51164733a4', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Governança de TI', 'Difícil', 'Uma avaliação examina apenas processos e conclui que avaliou todos os habilitadores. Qual erro ocorreu?', '["Demonstrou que informação não é relevante.","Reduziu a visão holística a uma única categoria.","Aplicou corretamente os sete habilitadores.","Incluiu habilitadores demais.","Confundiu pessoas com ativos físicos apenas."]'::jsonb, 1, 'Processos são apenas um dos sete habilitadores do COBIT 5.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.2.3, páginas 227–233 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('64333ddd-3cbe-5038-a0eb-73528856cdae', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Governança de TI', 'Médio', 'No COBIT 5, avaliar necessidades e definir direcionamento pertence principalmente à:', '["Gestão de incidentes exclusivamente.","Operação de serviços exclusivamente.","Administração de configuração exclusivamente.","Governança.","Construção de soluções exclusivamente."]'::jsonb, 3, 'Governança estabelece direção e monitora os objetivos acordados.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.2.3, páginas 227–233 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e561d2d1-1cd2-5891-a773-e1a963a299f7', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Governança de TI', 'Fácil', 'Qual domínio do COBIT 5 reúne os processos de governança?', '["APO.","EDM.","DSS.","MEA.","BAI."]'::jsonb, 1, 'EDM corresponde a avaliar, dirigir e monitorar.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.2.4, páginas 233–236 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b7773416-e953-5be3-87c6-6a216486ab9e', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Governança de TI', 'Médio', 'Qual domínio inclui estratégia, arquitetura e portfólio no COBIT 5?', '["DSS.","APO.","MEA.","EDM.","BAI."]'::jsonb, 1, 'APO reúne práticas de alinhamento, planejamento e organização.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.2.4, páginas 233–236 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6b53872d-1f07-5840-a5e2-53fc00daee6c', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Governança de TI', 'Médio', 'Construir e integrar soluções de TI está associado principalmente a qual domínio?', '["MEA.","APO.","BAI.","DSS.","EDM."]'::jsonb, 2, 'BAI trata de construir, adquirir e implementar soluções.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.2.4, páginas 233–236 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e83cbcbe-6ee0-5e6d-9783-7f4f26cec7a9', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Governança de TI', 'Médio', 'Gerenciar incidentes e problemas está em qual domínio do COBIT 5?', '["MEA.","APO.","DSS.","BAI.","EDM."]'::jsonb, 2, 'DSS abrange entrega e suporte dos serviços em operação.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.2.4, páginas 233–236 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ab0c0688-e02b-5f7d-9cfe-85bbec7634ef', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Governança de TI', 'Médio', 'Monitorar controles internos e conformidade externa pertence principalmente a qual domínio?', '["APO.","DSS.","MEA.","BAI.","EDM exclusivamente."]'::jsonb, 2, 'MEA reúne processos de monitoramento e avaliação do gerenciamento.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.2.4, páginas 233–236 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c7d3b6cc-96b7-55ff-b417-ae1030738c0f', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Governança de TI', 'Fácil', 'Quantos processos compõem o modelo de referência do COBIT 5 apresentado?', '["37.","26.","34.","50.","40."]'::jsonb, 0, 'O modelo distribui 37 processos entre cinco domínios.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.2.4, páginas 233–236 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f53ce8ad-368d-5c3f-a22d-ac52801b0732', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Governança de TI', 'Difícil', 'Qual distinção entre COBIT 4.1 e COBIT 5 é destacada na avaliação de processos?', '["O COBIT 5 adota capacidade de processos referenciada na ISO/IEC 15504.","O COBIT 4.1 já possui os mesmos sete habilitadores.","O COBIT 5 elimina avaliações.","O COBIT 5 usa exclusivamente certificação de produtos.","O COBIT 5 mede somente custo de hardware."]'::jsonb, 0, 'A edição destaca a transição do modelo de maturidade para capacidade de processos.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 6, seção 6.2.6, páginas 237–239 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false)
